})

Translate("ptBR", "magtoor", {
	title = "Magtoor",
	subtitle = "Voz do Refúgio",
	found = "O Refúgio",
	hint = "Fale com o draenei que lidera os exilados do Refúgio.",
	allegiance = "Draenei do Refúgio",
	sections = {
		{
			title = "Resumo",
			text = [=[Magtoor fala pelos exilados draenei do {link:the-harborage}Refúgio{/link}. Seu povo percorreu um longo caminho para chegar a {link:azeroth}Azeroth{/link}, e nem todos sobreviveram a ele inteiros. Os que perderam a razão se tornaram os perdidos. Tomaram o {link:fallow-sanctuary}Retiro Alqueivado{/link} e roubaram os cristais sagrados de draenethyst do Refúgio. Magtoor teme que, sem esses cristais, seu próprio povo também possa se perder.]=],
		},
		{
			title = "Importância",
			text = [=[Por meio de Magtoor, o mundo descobre o que os perdidos realmente são: não monstros nascidos do pântano, mas um povo quebrado por sua jornada.]=],
		},
		{
			title = "Feitos",
			text = [=[• Busca a devolução do draenethyst roubado pelos perdidos.
• Alegra-se com a morte de {link:noboru-the-cudgel}Noboru{/link}, que aterrorizava seu povo.]=],
		},
	},
	chapters = {
		{
			title = "Os Cristais Roubados",
